// Eco del asistente de emergencia (spec 005; contrato en specs/005-conexion-n8n-eco/contracts/).
// No guarda textos ni IPs: el límite es global y solo cuenta peticiones (constitución I y IV).
const LIMITE_POR_MINUTO = 30;
const VENTANA_MS = 60000;
const MAXIMO_MENSAJES = 20;
const MAXIMO_CARACTERES = 4000;
const ROLES = ["persona", "asistente"];

function aplicarLimite(datos, ahora) {
  if (typeof datos.inicioVentana !== "number" || ahora - datos.inicioVentana >= VENTANA_MS) {
    datos.inicioVentana = ahora;
    datos.cantidad = 0;
  }
  datos.cantidad += 1;
  return datos.cantidad <= LIMITE_POR_MINUTO;
}

function esMensajeValido(mensaje) {
  return (
    ROLES.includes(mensaje?.rol) &&
    typeof mensaje.texto === "string" &&
    mensaje.texto.length > 0 &&
    mensaje.texto.length <= MAXIMO_CARACTERES
  );
}

function esPeticionValida(cuerpo) {
  if (cuerpo === null || typeof cuerpo !== "object") return false;
  const { mensajes, ...otros } = cuerpo;
  return (
    Object.keys(otros).length === 0 &&
    Array.isArray(mensajes) &&
    mensajes.length > 0 &&
    mensajes.length <= MAXIMO_MENSAJES &&
    mensajes.every(esMensajeValido) &&
    mensajes.at(-1).rol === "persona"
  );
}

function salida(estado, cuerpo) {
  return [{ json: { estado, cuerpo } }];
}

const cuerpo = $input.first().json.body;
if (!aplicarLimite($getWorkflowStaticData("global"), Date.now())) {
  return salida(429, { error: "limite" });
}
if (!esPeticionValida(cuerpo)) return salida(400, { error: "peticion_invalida" });
return salida(200, { respuesta: "Eco: " + cuerpo.mensajes.at(-1).texto });
